private static Settings? _inst;
private static readonly object _gate = new();

public static Settings Instance
{
    get
    {
        if (_inst == null)                 // 1: without the lock
        {
            lock (_gate)
            {
                if (_inst == null)         // 2: under the lock
                    _inst = Settings.Load();
            }
        }
        return _inst;
    }
}

