var cache =
    new ConcurrentDictionary<string, Lazy<Task<Config>>>();

async Task<Config> GetAsync(string key)
{
    var lazy = cache.GetOrAdd(key,
        k => new Lazy<Task<Config>>(() => LoadAsync(k)));
    try
    {
        // all concurrent calls await ONE load
        return await lazy.Value;
    }
    catch
    {
        // remove exactly this failed entry
        cache.TryRemove(KeyValuePair.Create(key, lazy));
        throw;
    }
}
